# 【検証用】超兵器をすぐ作れるマップ。後で消してよい。
# 陸・空・海の研究所が自軍のもの。研究ポイントは作戦の test_lab で満タン、資金も多め。
# 研究所で建造すると3手番で完成する。敵は HP1 の歩兵1体（戦車の隣）で、撃てばいつでも勝てる。
[map]
name             = 【検証】超兵器
name@en = [TEST] Superweapons
width            = 16
height           = 10
turns            = 30
timeout_winner   = -1
funds0           = 30000
funds1           = 0

[terrain]
row = ............~~~~
row = ............~~~~
row = ..aM........~~~~
row = ............~~~~
row = ..HL.......pN~~~
row = ............~~~~
row = ..f.........~~~~
row = ............~~~~
row = ............~~~~
row = ............~~~~

[owners]
own = 2,4,0
own = 3,4,0
own = 2,6,0
own = 2,2,0
own = 3,2,0
own = 11,4,0
own = 12,4,0

[units]
unit = 0,INFANTRY,4,5,10
unit = 0,TANK,7,8,10
unit = 1,INFANTRY,8,8,1
